import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  HttpException,
  HttpStatus,
  Injectable,
  NotFoundException,
  UnauthorizedException,
} from '@nestjs/common';

interface User {
  id: number;
  email: string;
  role: string;
}

@Injectable()
export class UserRulesService {
  assertCanDelete(actor: User | undefined, targetId: number): void {
    if (!actor) throw new UnauthorizedException('Missing bearer token');
    if (targetId !== actor.id && actor.role !== 'admin') {
      throw new ForbiddenException('Only the owner can delete this order');
    }
  }

  assertValidEmail(email: string): void {
    if (!email.includes('@')) {
      throw new BadRequestException('Email must be a valid address');
    }
  }

  assertAvailable(email: string, taken: string[]): void {
    if (taken.includes(email)) {
      throw new ConflictException(`Email ${email} is already registered`);
    }
  }

  notFound(id: number): never {
    throw new NotFoundException(`User ${id} not found`);
  }

  throttle(retryAfter: number): never {
    throw new HttpException(
      { reason: 'Rate limit exceeded', retryAfter },
      HttpStatus.TOO_MANY_REQUESTS,
    );
  }
}

